def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    char_id = {ch: i for i, ch in enumerate(alphabet)}
    width = len(alphabet)
    transitions = [[-1] * width]
    failure = [0]
    bad = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = char_id[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * width)
                failure.append(0)
                bad.append(False)
            state = transitions[state][c]
        bad[state] = True

    queue = deque()
    for c in range(width):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        bad[state] |= bad[failure[state]]
        for c in range(width):
            child = transitions[state][c]
            fallback = transitions[failure[state]][c]
            if child == -1:
                transitions[state][c] = fallback
            else:
                failure[child] = fallback
                queue.append(child)

    states = [s for s in range(len(transitions)) if not bad[s]]
    index = {s: i for i, s in enumerate(states)}
    size = len(states)
    matrix = [[0] * size for _ in range(size)]

    for state in states:
        row = matrix[index[state]]
        for target in transitions[state]:
            if not bad[target]:
                row[index[target]] += 1

    def multiply(a, b):
        result = [[0] * size for _ in range(size)]
        for i, a_row in enumerate(a):
            result_row = result[i]
            for k, value in enumerate(a_row):
                if value:
                    for j, other in enumerate(b[k]):
                        if other:
                            result_row[j] += value * other
            for j in range(size):
                result_row[j] %= MOD
        return result

    vector = [0] * size
    vector[index[0]] = 1

    while n:
        if n & 1:
            updated = [0] * size
            for i, value in enumerate(vector):
                if value:
                    for j, count in enumerate(matrix[i]):
                        if count:
                            updated[j] += value * count
            vector = [value % MOD for value in updated]
        n >>= 1
        if n:
            matrix = multiply(matrix, matrix)

    return sum(vector) % MOD
